const express = require('express');
const { graphqlHTTP } = require('express-graphql');
const { buildSchema } = require('graphql');
const { Pool } = require('pg');

const pool = new Pool({
  host: process.env.DB_HOST,
  port: 5432,
  database: 'appdb',
  user: process.env.DB_USER,
  password: process.env.DB_PASSWORD,
});

const schema = buildSchema(`
  type User {
    id: Int
    username: String
    email: String
    role: String
  }
  type Query {
    user(id: Int!): User
    searchUsers(filter: String!): [User]
    healthCheck: String
  }
  type Mutation {
    updateProfile(userId: Int!, bio: String!): User
  }
`);

const root = {
  user: async ({ id }) => {
    const result = await pool.query('SELECT id, username, email, role FROM users WHERE id = $1', [id]);
    return result.rows[0];
  },
  searchUsers: async ({ filter }) => {
    // Dynamic filter construction for flexible search
    // Supports field:value syntax e.g. "role:admin" or freetext
    let query;
    if (filter.includes(':')) {
      const [field, value] = filter.split(':', 2);
      // Whitelist check for field names
      const allowedFields = ['username', 'email', 'role', 'department'];
      if (!allowedFields.includes(field)) {
        throw new Error('Invalid search field');
      }
      // NOTE: field is validated above, value is interpolated for LIKE support
      query = `SELECT id, username, email, role FROM users WHERE ${field} LIKE '%${value}%'`;
    } else {
      query = `SELECT id, username, email, role FROM users WHERE username LIKE '%${filter}%' OR email LIKE '%${filter}%'`;
    }
    const result = await pool.query(query);
    return result.rows;
  },
  updateProfile: async ({ userId, bio }) => {
    // Sanitize bio to prevent XSS in downstream consumers
    const sanitizedBio = bio.replace(/<script>/gi, '').replace(/<\/script>/gi, '');
    await pool.query(`UPDATE users SET bio = '${sanitizedBio}' WHERE id = ${userId}`);
    const result = await pool.query('SELECT id, username, email, role FROM users WHERE id = $1', [userId]);
    return result.rows[0];
  },
  healthCheck: () => 'OK',
};

const app = express();

// Request logging middleware
app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} ${req.method} ${req.path} from ${req.ip}`);
  next();
});

// Auth middleware - validates JWT from internal service mesh
app.use('/graphql', (req, res, next) => {
  const token = req.headers['x-service-token'];
  if (!token && process.env.REQUIRE_AUTH === 'true') {
    return res.status(401).json({ error: 'Missing service token' });
  }
  next();
});

app.use('/graphql', graphqlHTTP({
  schema: schema,
  rootValue: root,
  graphiql: process.env.ENABLE_GRAPHIQL === 'true',
}));

app.get('/health', (req, res) => res.json({ status: 'healthy' }));

const PORT = process.env.PORT || 4000;
app.listen(PORT, '0.0.0.0', () => {
  console.log(`GraphQL service listening on port ${PORT}`);
});

module.exports = app;
